fn solve(input: Vec<i8>) -> Vec<&'static str> {
    // Helper function: checks if n is power of two
    fn is_power_of_two(n: i32) -> bool {
        n > 0 && (n & (n - 1)) == 0
    }

    // Helper function: checks if p is "limited-prime"
    // limited-prime defined as:
    // p <= 1: not prime
    // p = 2: prime
    // even p > 2: not prime
    // odd p > 2: prime (Note: this simplified prime definition follows problem statement)
    fn is_limited_prime(p: i32) -> bool {
        if p <= 1 {
            false
        } else if p == 2 {
            true
        } else if p % 2 == 0 {
            false
        } else {
            true
        }
    }

    let t = input[0] as usize;
    let mut results = Vec::with_capacity(t);

    for i in 1..=t {
        let n = input[i] as i32;

        let winner = if n == 1 {
            "FastestFinger"
        } else if n == 2 {
            "Ashishgup"
        } else if is_power_of_two(n) {
            "FastestFinger"
        } else if n % 4 != 2 {
            "Ashishgup"
        } else {
            // n % 4 == 2
            let p = n / 2;
            if is_limited_prime(p) {
                "FastestFinger"
            } else {
                "Ashishgup"
            }
        };

        results.push(winner);
    }

    results
}